// trees
for(let x=50;x<world.w;x+=155){for(let y=45;y<world.h;y+=155){if(Math.abs(x-world.w/2)<100||Math.abs(y-world.h/2)<90)continue;ctx.fillStyle='#79573b';ctx.fillRect(x-4,y+4,8,17);ctx.fillStyle=rural?'#4d8554':'#367d53';ctx.beginPath();ctx.arc(x,y,15,0,Math.PI*2);ctx.fill();}}
// traffic
for(const c of traffic){ctx.fillStyle=c.police?'#f7f8f3':'#e1b56b';ctx.fillRect(c.x-18,c.y-10,36,20);ctx.fillStyle='#203e54';ctx.fillRect(c.x-6,c.y-8,13,16);if(c.police){ctx.fillStyle=siren?'#df4040':'#2b7bc1';ctx.fillRect(c.x-5,c.y-12,10,4);}}
