// player / vehicle
if(save.inVehicle){ctx.fillStyle='#f4f5f2';ctx.fillRect(carX-24,carY-14,48,28);ctx.fillStyle='#235d9b';ctx.fillRect(carX-8,carY-12,17,24);ctx.fillStyle=siren?'#e74c3c':'#2879c9';ctx.fillRect(carX-5,carY-17,11,5);ctx.fillStyle='#171f27';ctx.fillRect(carX-17,carY-17,8,5);ctx.fillRect(carX+9,carY-17,8,5);}else{ctx.fillStyle='#173c59';ctx.fillRect(playerX-7,playerY-10,14,20);ctx.fillStyle='#d5a57d';ctx.fillRect(playerX-5,playerY-17,10,8);ctx.fillStyle='#132e45';ctx.fillRect(playerX-6,playerY-21,12,5);ctx.fillStyle='#f4d46b';ctx.fillRect(playerX-2,playerY-6,4,5);}
